from datetime import date, datetime, time, timedelta
import threading
from django.utils import timezone
from django.core.files.storage import default_storage
from dateutil.relativedelta import relativedelta
from django.db import models
from django.contrib.auth.models import AbstractUser
from ..utils.utility import Utility
from .._helpers.person import Person
from .._helpers.fields import (TINY_BLANK_CHAR, VALID_MYSQL_MIN_DATE, VOID, 
															FILE_SIZE_VALIDATOR, DEFAULT_USER_TYPED, LANG_CHOICES)
from typing import Any, Optional, Dict, List, Union

_user = threading.local()

class CurrentUserMiddleware:
	def __init__(self, get_response: Any) -> None:
		self.get_response = get_response
	def __call__(self, request: Any) -> Any:
		_user.value = request.user
		response = self.get_response(request)
		return response

def get_current_user() -> Optional["User"]:
	return getattr(_user, "value", None)

class User(Person, AbstractUser):
	password = models.CharField(max_length=128)
	type = models.CharField(**DEFAULT_USER_TYPED, db_index=True)
	avatar = models.ImageField(upload_to="avatars/", storage=default_storage, validators=[FILE_SIZE_VALIDATOR], **VOID)
	avatar_url = models.URLField(max_length=200, **VOID)
	settings = None
	storage_limit = models.PositiveIntegerField(**VOID)
	lang = models.CharField(max_length=20, default="en", choices=LANG_CHOICES)
	mode = models.CharField(**TINY_BLANK_CHAR)
	delete_status = models.BooleanField(default=False)
	plan = models.CharField(**TINY_BLANK_CHAR)
	plan_expire_date = models.DateField(**VOID, validators=[VALID_MYSQL_MIN_DATE])
	requested_plan = models.CharField(**TINY_BLANK_CHAR)
	last_login_at = models.DateTimeField(**VOID)
	birth_date = models.DateField(validators=[VALID_MYSQL_MIN_DATE], **VOID)

	@property
	def profile(self) -> str:
		if self.avatar and default_storage.exists(self.avatar.name):
			return default_storage.url(self.avatar.name)
		return default_storage.url("avatar.png")

	def auth_id(self) -> Any:
		return self.id

	def creator_id(self) -> Any:
		return self.id if self.type in ["company", "super admin"] else self.created_by

	def owner_id(self) -> Any:
		return self.creator_id()

	def owner_details(self) -> Optional["User"]:
		from django.contrib.auth import get_user_model
		UserModel = get_user_model()
		if self.type in ["company", "super admin"]:
			return UserModel.objects.filter(id=self.id).first()
		return UserModel.objects.filter(id=self.created_by).first()

	def current_language(self) -> str:
		return self.lang

	def price_format(self, price: float) -> str:
		settings_data = Utility.settings()
		decimal_number = Utility.get_val_by_name("decimal_number") or 0
		symbol = settings_data["site_currency_symbol"]
		fmt = f"{{:.{decimal_number}f}}"
		formatted = fmt.format(price)
		return f"{symbol}{formatted}" if settings_data.get("site_currency_symbol_position") == "pre" else f"{formatted}{symbol}"

	@staticmethod
	def price_formats(price: float) -> str:
		settings_data = Utility.settings()
		decimal_number = Utility.get_val_by_name("decimal_number") or 0
		symbol = settings_data["site_currency_symbol"]
		fmt = f"{{:.{decimal_number}f}}"
		formatted = fmt.format(price)
		return f"{symbol}{formatted}" if settings_data.get("site_currency_symbol_position") == "pre" else f"{formatted}{symbol}"

	def currency_symbol(self) -> str:
		settings_data = Utility.settings()
		return settings_data["site_currency_symbol"]

	def date_format(self, date_value: Union[str, datetime, date]) -> str:
		settings_data = Utility.settings()
		if isinstance(date_value, (datetime, date)):
			dt = date_value
		else:
			dt = datetime.strptime(date_value, "%Y-%m-%d")
		return dt.strftime(settings_data["site_date_format"])

	def time_format(self, time_value: Union[str, datetime, time]) -> str:
		settings_data = Utility.settings()
		if isinstance(time_value, (time, datetime)):
			dt = time_value if isinstance(time_value, datetime) else datetime.combine(date.today(), time_value)
		else:
			dt = datetime.strptime(time_value, "%H:%M:%S")
		return dt.strftime(settings_data["site_time_format"])

	def purchase_number_format(self, number: int) -> str:
		settings_data = Utility.settings()
		return f"{settings_data['purchase_prefix']}{number:05d}"

	def pos_number_format(self, number: int) -> str:
		settings_data = Utility.settings()
		return f"{settings_data['pos_prefix']}{number:05d}"

	def invoice_number_format(self, number: int) -> str:
		settings_data = Utility.settings()
		return f"{settings_data['invoice_prefix']}{number:05d}"

	def proposal_number_format(self, number: int) -> str:
		settings_data = Utility.settings()
		return f"{settings_data['proposal_prefix']}{number:05d}"

	def contract_number_format(self, number: int) -> str:
		settings_data = Utility.settings()
		return f"{settings_data['contract_prefix']}{number:05d}"

	def bill_number_format(self, number: int) -> str:
		settings_data = Utility.settings()
		return f"{settings_data['bill_prefix']}{number:05d}"

	def expense_number_format(self, number: int) -> str:
		settings_data = Utility.settings()
		return f"{settings_data['expense_prefix']}{number:05d}"

	def journal_number_format(self, number: int) -> str:
		settings_data = Utility.settings()
		return f"{settings_data['journal_prefix']}{number:05d}"

	def get_plan(self) -> Optional[Any]:
		from ..planning.plan import Plan
		return Plan.objects.filter(id=self.plan).first()

	def assign_plan(self, plan_id: Any, company_id: int = 0) -> Dict[str, Any]:
		from ..planning.plan import Plan
		from ..individuals.customer import Customer
		from ..companies.vendor import Vendor
		plan = Plan.objects.filter(id=plan_id).first()
		if plan:
			self.plan = plan.id
			now = timezone.now()
			if plan.duration == "month":
				self.plan_expire_date = (now + relativedelta(months=+1)).date()
			elif plan.duration == "year":
				self.plan_expire_date = (now + relativedelta(years=+1)).date()
			else:
				self.plan_expire_date = None
			self.save()
			user_id = company_id if company_id != 0 else self.creator_id()
			users = User.objects.filter(created_by=user_id).exclude(type__in=["super admin", "company", "client"])
			clients = User.objects.filter(created_by=user_id, type="client")
			customers = Customer.objects.filter(created_by=user_id)
			vendors = Vendor.objects.filter(created_by=user_id)
			if plan.max_users == -1:
				for user in users:
					user.is_active = True
					user.save()
			else:
				user_count = 0
				for user in users:
					user_count += 1
					user.is_active = user_count <= plan.max_users
					user.save()
			if plan.max_clients == -1:
				for client in clients:
					client.is_active = True
					client.save()
			else:
				client_count = 0
				for client in clients:
					client_count += 1
					client.is_active = client_count <= plan.max_clients
					client.save()
			if plan.max_customers == -1:
				for customer in customers:
					customer.is_active = True
					customer.save()
			else:
				customer_count = 0
				for customer in customers:
					customer_count += 1
					customer.is_active = customer_count <= plan.max_customers
					customer.save()
			if plan.max_vendors == -1:
				for vendor in vendors:
					vendor.is_active = True
					vendor.save()
			else:
				vendor_count = 0
				for vendor in vendors:
					vendor_count += 1
					vendor.is_active = vendor_count <= plan.max_vendors
					vendor.save()
			return {"is_success": True}
		else:
			return {"is_success": False, "error": "Plan is deleted."}

	def customer_number_format(self, number: int) -> str:
		settings_data = Utility.settings()
		return f"{settings_data['customer_prefix']}{number:05d}"

	def vendor_number_format(self, number: int) -> str:
		settings_data = Utility.settings()
		return f"{settings_data['vendor_prefix']}{number:05d}"

	def count_users(self) -> int:
		from django.contrib.auth import get_user_model
		UserModel = get_user_model()
		return UserModel.objects.filter(created_by=self.creator_id()).exclude(type__in=["super admin", "company", "client"]).count()

	def count_company(self) -> int:
		from django.contrib.auth import get_user_model
		UserModel = get_user_model()
		return UserModel.objects.filter(created_by=self.creator_id(), type="company").count()

	def count_order(self) -> int:
		from ..activity.order import Order
		return Order.objects.count()

	def count_plan(self) -> int:
		from ..planning.plan import Plan
		return Plan.objects.count()

	def count_paid_company(self) -> int:
		from django.contrib.auth import get_user_model
		UserModel = get_user_model()
		return UserModel.objects.filter(created_by=self.id, type="company").exclude(plan__in=[0, 1]).count()

	def count_customers(self) -> int:
		from ..individuals.customer import Customer
		return Customer.objects.filter(created_by=self.creator_id()).count()

	def count_vendors(self) -> int:
		from ..companies.vendor import Vendor
		return Vendor.objects.filter(created_by=self.creator_id()).count()

	def count_invoices(self) -> int:
		from ..bills.invoice import Invoice
		return Invoice.objects.filter(created_by=self.creator_id()).count()

	def count_bills(self) -> int:
		from ..bills.bill import Bill
		return Bill.objects.filter(created_by=self.creator_id()).count()

	def today_income(self) -> float:
		today = timezone.now().date()
		from django.db.models import Sum
		from ..bills.revenue import Revenue
		from ..bills.invoice import Invoice
		revenue = Revenue.objects.filter(created_by=self.creator_id(), date=today).aggregate(total=Sum("amount"))["total"] or 0
		invoices = Invoice.objects.filter(created_by=self.creator_id(), send_date=today)
		invoice_total = sum(invoice.get_total() for invoice in invoices)
		return revenue + invoice_total

	def today_expense(self) -> float:
		today = timezone.now().date()
		from django.db.models import Sum
		from ..bills.payment import Payment
		from ..bills.bill import Bill
		payment_total = Payment.objects.filter(created_by=self.creator_id(), date=today).aggregate(total=Sum("amount"))["total"] or 0
		bills = Bill.objects.filter(created_by=self.creator_id(), send_date=today)
		bill_total = sum(bill.get_total() for bill in bills)
		return payment_total + bill_total

	def income_current_month(self) -> float:
		now = timezone.now()
		current_year = now.year
		current_month = now.month
		from django.db.models import Sum
		from ..bills.revenue import Revenue
		from ..bills.invoice import Invoice
		revenue = Revenue.objects.filter(created_by=self.creator_id(), date__year=current_year, date__month=current_month).aggregate(total=Sum("amount"))["total"] or 0
		invoices = Invoice.objects.filter(created_by=self.creator_id(), send_date__year=current_year, send_date__month=current_month)
		invoice_total = sum(invoice.get_total() for invoice in invoices)
		return revenue + invoice_total

	def income_cat(self) -> float:
		now = timezone.now()
		current_month = now.month
		from django.db.models import Sum
		from ..bills.revenue import Revenue
		from ..bills.invoice import Invoice
		revenue = Revenue.objects.filter(created_by=self.creator_id(), date__month=current_month).aggregate(total=Sum("amount"))["total"] or 0
		invoices = Invoice.objects.filter(created_by=self.creator_id(), send_date__month=current_month)
		invoice_total = sum(invoice.get_total() for invoice in invoices)
		return revenue + invoice_total

	def expense_current_month(self) -> float:
		now = timezone.now()
		current_month = now.month
		from django.db.models import Sum
		from ..bills.payment import Payment
		from ..bills.bill import Bill
		payment_total = Payment.objects.filter(created_by=self.creator_id(), date__month=current_month).aggregate(total=Sum("amount"))["total"] or 0
		bills = Bill.objects.filter(created_by=self.creator_id(), send_date__month=current_month)
		bill_total = sum(bill.get_total() for bill in bills)
		return payment_total + bill_total

	def get_inc_exp_bar_chart_data(self) -> Dict[str, Any]:
		import calendar
		now = timezone.now().date()
		current_year = now.year
		months = list(calendar.month_name)[1:]
		data: Dict[str, Any] = {"month": months}
		income_arr: List[Union[str, int]] = []
		expense_arr: List[Union[str, int]] = []
		from django.db.models import Sum
		from ..bills.bill import Bill
		from ..bills.invoice import Invoice
		from ..bills.payment import Payment
		from ..bills.revenue import Revenue
		for month in range(1, 13):
			monthly_income = Revenue.objects.filter(created_by=self.creator_id(), date__year=current_year, date__month=month).aggregate(total=Sum("amount"))["total"] or 0
			invoices = Invoice.objects.filter(created_by=self.creator_id(), send_date__year=current_year, send_date__month=month)
			invoice_total = sum(invoice.get_total() for invoice in invoices)
			total_income = monthly_income + invoice_total
			income_arr.append(str(format(total_income, ".2f")).replace(",", "") if total_income else 0)
			monthly_expense = Payment.objects.filter(created_by=self.creator_id(), date__year=current_year, date__month=month).aggregate(total=Sum("amount"))["total"] or 0
			bills = Bill.objects.filter(created_by=self.creator_id(), send_date__year=current_year, send_date__month=month)
			bill_total = sum(bill.get_total() for bill in bills)
			total_expense = monthly_expense + bill_total
			expense_arr.append(str(format(total_expense, ".2f")).replace(",", "") if total_expense else 0)
		data["income"] = income_arr
		data["expense"] = expense_arr
		return data

	def get_inc_exp_line_chart_date(self) -> Dict[str, Any]:
		now = timezone.now().date()
		arr_date = [now - timedelta(days=i) for i in range(15)]
		arr_date_format = [d.strftime("%d-%b") for d in arr_date]
		data: Dict[str, Any] = {"day": arr_date_format}
		income_arr: List[str] = []
		expense_arr: List[str] = []
		from django.db.models import Sum
		from ..bills.bill import Bill
		from ..bills.invoice import Invoice
		from ..bills.payment import Payment
		from ..bills.revenue import Revenue
		for date_val in arr_date:
			day_income = Revenue.objects.filter(created_by=self.creator_id(), date=date_val).aggregate(total=Sum("amount"))["total"] or 0
			invoices = Invoice.objects.filter(created_by=self.creator_id(), send_date=date_val)
			invoice_total = sum(invoice.get_total() for invoice in invoices)
			income_amount = day_income + invoice_total
			income_arr.append(str(format(income_amount, ".2f")).replace(",", ""))
			day_expense = Payment.objects.filter(created_by=self.creator_id(), date=date_val).aggregate(total=Sum("amount"))["total"] or 0
			bills = Bill.objects.filter(created_by=self.creator_id(), send_date=date_val)
			bill_total = sum(bill.get_total() for bill in bills)
			expense_amount = day_expense + bill_total
			expense_arr.append(str(format(expense_amount, ".2f")).replace(",", ""))
		data["income"] = income_arr
		data["expense"] = expense_arr
		return data

