	def weekly_invoice(self) -> Dict[str, Union[int, float]]:
		start_date = timezone.now().date() - timedelta(days=7)
		current_date = timezone.now().date()
		from ..bills.invoice import Invoice
		invoices = Invoice.objects.filter(created_by=self.creator_id(), issue_date__range=[start_date, current_date])
		invoice_total = invoice_paid = invoice_due = 0
		for inv in invoices:
			total = inv.get_total()
			due = inv.get_due()
			invoice_total += total
			invoice_paid += (total - due)
			invoice_due += due
		return {"invoiceTotal": invoice_total, "invoicePaid": invoice_paid, "invoiceDue": invoice_due}

