	def created_total_project_task(self) -> int:
		from ..planning.project_task import ProjectTask
		if self.type == "company":
			return ProjectTask.objects.filter(project__created_by=self.creator_id()).count()
		elif self.type == "client":
			return ProjectTask.objects.filter(project__client_id=self.auth_id()).count()
		else:
			return ProjectTask.objects.filter(project__projectuser__user_id=self.auth_id()).count()

	def project_complete_task(self, project_last_stage: Any) -> int:
		from ..planning.project import Project
		from ..planning.project_task import ProjectTask
		if self.type == "company":
			return ProjectTask.objects.filter(project__created_by=self.creator_id(), stage_id=project_last_stage).count()
		elif self.type == "client":
			user_projects = Project.objects.filter(client_id=self.id).values_list("id", flat=True)
			return ProjectTask.objects.filter(project_id__in=user_projects, stage_id=project_last_stage).count()
		else:
			return ProjectTask.objects.filter(project__projectuser__user_id=self.auth_id(), stage_id=project_last_stage).count()

	def created_top_due_task(self) -> Any:
		today = timezone.now().date()
		from ..planning.project import Project
		from ..planning.project_task import ProjectTask
		if self.type == "company":
			return ProjectTask.objects.filter(project__created_by=self.creator_id(), end_date__gt=today).select_related("project", "projectstage").order_by("end_date")[:5]
		elif self.type == "client":
			user_projects = Project.objects.filter(client_id=self.id).values_list("id", flat=True)
			return ProjectTask.objects.filter(project_id__in=user_projects, end_date__gt=today)[:5]
		else:
			return ProjectTask.objects.filter(project__projectuser__user_id=self.auth_id(), end_date__gt=today).select_related("project", "projectstage").order_by("end_date")[:5]

