	@staticmethod
	def user_current_location() -> Optional[Any]:
		current_user = get_current_user()
		if not current_user:
			return None
		company_id = current_user.company_id()
		from ..shapes.location import Location
		if current_user.user_type == "company":
			location = Location.objects.filter(id=current_user.current_location, company_id=company_id, is_active=True).first()
			return location.id if location else 0
		elif current_user.user_type not in ["company", "super admin"]:
			if current_user.current_location == 0:
				current_user.current_location = current_user.location_id
			location = Location.objects.filter(id=current_user.current_location, company_id=company_id).first()
			return location.id if location else None

